BEGIN
    DECLARE v_notifications_email BOOLEAN DEFAULT FALSE;
    DECLARE v_notifications_sms BOOLEAN DEFAULT FALSE;
    DECLARE v_confidentialite ENUM('PUBLIC', 'PRIVATE', 'FRIENDS_ONLY') DEFAULT 'PUBLIC';
    
    -- Déterminer les paramètres selon le rôle
    IF NEW.role IS NOT NULL THEN
        IF UPPER(NEW.role) = 'PATIENT' THEN
            SET v_notifications_sms = TRUE;
            SET v_confidentialite = 'FRIENDS_ONLY';
        ELSEIF UPPER(NEW.role) = 'PSY_COACH' THEN
            SET v_notifications_email = TRUE;
            SET v_notifications_sms = TRUE;
            SET v_confidentialite = 'PUBLIC';
        END IF;
    END IF;
    
    -- Créer le user_profile
    INSERT INTO user_profile (
        user_id,
        avatar,
        bio,
        date_naissance,
        langue,
        notifications_email,
        notifications_sms,
        parametres_confidentialite,
        date_creation,
        date_modification
    )
    VALUES (
        NEW.id,
        NULL,
        NULL,
        NULL,
        'FR',
        v_notifications_email,
        v_notifications_sms,
        v_confidentialite,
        NOW(),
        NOW()
    );
END
